    "location": "北京、杭州、上海",
    "source": "https://campus-talent.alibaba.com/campus/position/199907820065",
    "description": "千问Qwen是由阿里巴巴自主研发的超大规模语言模型，具备跨语言、跨任务的理解与生成能力。Qwen系列模型，涵盖参数量从几百 M 到 T 级的基座大语言模型，并相继推出Qwen-VL、Qwen-Audio、Qwen-Omni、Qwen-Coder、Qwen-Image等系列模型。从多轮对话到代码生成，从逻辑推理到内容创作，从单一多模态到全模态统一理解生成，Qwen 正在打造全球领先的全模态模型技术体系，推动AI在企业服务、开发者生态、个人用户等领域的深度应用，引领下一代人工智能的发展。\n\n千问Qwen全模态统一理解生成前沿技术研究，团队在多个方向上进行探索（具体如下罗列），若你对以下一个或者多个课题感兴趣均欢迎投递：\n1. 模型架构与学习机制探索\n1)预训练与后训练技术：持续提升模型的理解力、推理力与泛化能力。\n2)探索下一代学习范式，如自监督学习、动态训练策略、知识蒸馏等。\n2. 多模态与多智能体感知交互系统\n1)打造 Omni 基座模型，实现文本、语音、视觉等多模态一体化理解与生成，推动世界模型的发展。\n2)开发超智能的 Coding Agent，打通语言与代码之间的桥梁，连接 AI 与数字世界。\n3)构建下一代 AI 交互系统，在 GUI Agent、视频理解等前沿场景，探索 AI 自主执行、扩展、进化的可能性。\n3. 数据建设与性能优化\n1)数据工程：设计高效的数据处理管线，持续提升自然语言、代码、多模态等数据质量与规模。\n2)推理优化：探索模型高并发服务下，算法及系统框架侧技术创新与优化，包括但不限于训练推理协同优化、模型推理新范式。\n4. 评测与安全体系\n1)构建下一代大模型评估系统，覆盖推理、生成、可控性等多个维度。\n2)关注模型内生安全，追求 AI 对人类有益且可控，参与对抗攻击检测、伦理约束建模等工作。",
    "requirementsText": "1. 来自全球Top高校计算机科学、人工智能、数学、物理或相关领域应届博士/顶尖硕士毕业生；\n2. 在深度学习、大规模模型训练、优化算法、生成式模型、自监督学习等领域有扎实的理论基础和实践经验，并至少在其中一个方向产生具有行业影响力的创新性成果；\n3. 在国际顶级计算机会议/期刊（如NeurIPS、ICML、ICLR、ACL、TPAMI等）以一作身份发表过多篇论文，或在开源社区、竞赛中展示出引领性的研究成果；\n4. 对基础模型的前沿问题有持续热情，具备独立思考能力和系统性研究思维，敢于挑战现有范式。能够独立应用技术解决复杂问题，主导或深度参与过有影响力项目的人选优先；\n5. 具备扎实的代码功底，熟悉PyTorch/TensorFlow等框架，能够高效实现复杂模型结构并进行大规模训练（曾参与千卡集群项目者优先）；ACM/ICPC，topcoder等编程比赛获奖者优先；\n6. 持续关注专业的前沿领域。不满足于“跟随热点”，有志于定义下一代基础模型的进化方向；\n7. 具备跨学科视野与协作意识，能够与工程、产品等多学科团队紧密合作，推动研究成果快速落地并产生实际影响力。",
