    "source": "https://campus-talent.alibaba.com/campus/position/199907720114",
    "description": "在这里，你将参与传统视频编码器（包括但不限于HEVC/VVC）优化，在保障画质体验的前提下，尽可能节省带宽；\n在这里，你将探索基于语义的内容感知编码优化，深度学习编码，AIGC编码等前沿课题；\n在这里，你将参与视频编码与处理联合优化，在标准编码框架的基础上，借助AI领域的新技术成果来研究视频信号的表征、编码与处理，将视频前后处理与编码联合优化，提升端到端压缩效果；\n在这里，你将帮助淘宝直播等大型的视频传输场景设计QoS算法，追求超低延时、极速播放等用户体验，并支持各种弱网环境下的最优的视频流畅度和优雅的画质降级。\n\n岗位研究课题：\n【传统编码】基于HEVC/VVC等传统编解码器的内核优化\n【智能编码】基于语义的内容感知编码优化，深度学习编码，生成式编码等\n【质量评价】视频画质、图像画质、人脸美感评价算法，AIGC内容质量评价\n【传输算法】基于实时传输协议的全链路拥塞控制算法和自适应码率算法",
    "requirementsText": "1、毕业时间在2026年11月之后的在校本硕博同学，计算机相关专业，有视频或图像编码和处理研究背景；\n2、精通C++和C编程，并熟悉视频编解码标准，如AVC、HEVC、VVC、AV1、AVS系列，有相关标准提案，或使用视频编码开源软件或标准参考软件（如X264，X265，VVENC, VTM，JEM，HM，SHM，JM和JSVM）的经验优先考虑；\n3、熟练掌握超分辨率、去模糊、降噪及色彩增强等方向的经典画质增强算法或无参视频质量评价算法；\n4、熟悉手机端的图像、视频算法的算法开发，包括人脸人体关键点，三维人脸人体重建，美颜、美妆等；\n5、熟悉扩散模型及其在视频图像处理、编码、生成中的应用，有相关项目经验或在高影响力开源项目中作出核心贡献； \n6、有出色的学习能力、分析研究及创新能力、优异的学术产出。 \n\n【加分项】 \n1. 在NTIRE、AIM、AIS、MSU等权威竞赛获奖者；\n2. ICCV、CVPR、ECCV、TPAMI、T-CSVT、T-IP 等顶级会议和期刊发表论文者；",
