    "source": "https://campus-talent.alibaba.com/campus/position/199907720116",
    "description": "团队是淘天集团内专注于创新和优化搜索技术的核心团队，支撑淘天超大规模检索、相关性、预估、Query理解、顶层机制设计、AI搜，直接驱动千亿级GMV。我们的任务是通过持续研发高效、精准的搜索算法，以提升用户的在线购物体验和满意度，进而推动电商平台的商业成功。在这一关键角色中，你将参与淘宝搜索功能的核心算法研究，特别是专注于大模型在信息检索领域的应用、AI创新产品和AI搜等创新领域。我们深度理解搜索引擎的工作原理，在生成式排序/检索、AI大模型全链路应用、模型Scaling和Infra、多模态技术、AI Agent等技术方面持续深耕。\n\n相关研究课题细分方向如下：\n-基于Agentic AI探索包含不但不限于AI搜索、Search Agent、Native链路交互体验、Skills驱动等搜索全新升级。\n-基于VLLM&Agent建设全域全模态相关性评判能力。\n-基于LLM&用户终身行为的个性化Memory，打造更全、更懂、更准的用户意图赋能搜索全链路。\n-基于LLM结合世界知识&推理&User-Query-LLM-Wiki，打造电商领域个性化生成式推荐的技术行业标杆。\n-基于VLLM&多模态&生成式推荐，打造基于纯模态的新品链路，提升新品在手淘的分发效率。 \n-基于Agentic架构实现VLLM用户深度意图推理&动态导购策略规划&智能触发决策，打造流内可交互式的AI搜索能力，提升搜索体验和承接效率。 \n-基于Agentic AI探索全场景、多模态的生成式推词能力，预测淘宝用户全周期的电商购物需求，提升搜索导购效率 \n-基于VLLM&AIGC，构建专业穿搭大模型及搭配内容知识库，低成本、规模化生产高质量跨店穿搭内容，全面覆盖穿搭类搜索需求。",
