    "source": "https://campus-talent.alibaba.com/campus/position/199907780108",
    "description": "【团队介绍-智能创作与AI应用】\nAIGC 时代，内容创意制作正在发生巨大的变革，团队致力于研发最先进的图像和视频生成 & 编辑模型，为淘天搜推广营销场景提供丰富的内容素材，为商家提供更好用的内容创作工具。\n团队专注于 CV、NLP 等多模态和多媒体技术进行内容创作、内容理解方向的算法工作。团队耕耘技术多年，在电商创意素材生成领域有广泛的业界影响力。集中核心资源研发视频多版视频生成模型、视频编辑编辑模型和图像编辑模型，是淘天集团多模态生成基础模型的研发主力。同时通过电商图像编辑、图生视频、首尾帧生视频、参考图生视频、图文海报制作、短视频制作等电商智能创作模型（产品），支持阿里妈妈创意中心、万相实验室等原生AIGC产品和淘宝商家的智能创作工具。研究成果发表在 CVPR、ICCV、TPAMI、NIPS、AAAI、ACM MM、WWW 等领域知名会议。\n\n相关研究课题细分方向如下：\n● 大规模通用视频基础模型\n● 视频编辑与参考生成视频\n● 通用图像编辑模型",
