    "source": "https://campus-talent.alibaba.com/campus/position/199907820096",
    "description": "阿里巴巴国际数字商业集团（AIDC）的智能技术-智能引擎团队，负责支撑包括Lazada、AliExpress、Miravia、Daraz等在内的阿里巴巴全球化电商平台的搜索、推荐、广告、用户增长等核心技术。我们致力于将AI领域最前沿的技术（如深度学习、大模型、Agent等）与全球化电商业务的复杂挑战深度融合，持续打造更智能、更极致的全球购物体验，并赋能数百万商家实现数字化经营提效。\n\n选择我们，意味着：\n● 投身全球领先的电商智能战场： 深度参与高速增长、充满活力的全球化电商业务，直面海量用户与复杂场景的挑战;\n● 塑造最前沿的AI技术影响力： 与顶尖技术伙伴一起，探索并构建驱动未来全球电商发展的核心AI能力，你的技术将影响全球数亿消费者和百万商家;\n● 无限可能的职业发展空间： 在阿里巴巴国际化的大舞台上，接触世界级的技术难题与业务规模，获得技术深度与业务视野的双重飞跃。\n\n你将参与：\n1. 打造支持 Agentic AI、多模态、长上下文推理的超大规模训练架构;\n2. 深度优化 FlashAttention、PagedAttention、Continuous Batching 等尖端加速技术;\n3. 推动 LLM 与 Recommender System 融合架构的首次规模化落地.\n\n你将负责：\n1. 打造行业领先的AI工程平台： 设计并构建支撑算法模型高效迭代的标准化平台体系（特征平台、训练平台、在线推理框架等），打通算法创新与业务验证的“任督二脉”，加速模型价值落地;\n2. 攻坚大模型工程化挑战： 深入探索生成式AI（AIGC）技术在实际业务中的规模化落地，主导大模型训练、推理加速、性能优化等核心工程难题的解决;\n3. 开拓AI创新应用的边界： 积极探索AI在搜索/推荐/广告（搜推广）等核心场景的颠覆性应用（如生成式召回、生成式排序、行为大模型），以及AI Agent技术在智能运维、资源优化、智能客服助手等领域的创新实践，为业务创造新价值。",
