    "description": "从主流模型支持到算子代码生成，AI编译器是自研 AI 芯片快速支持模型的核心技术。随着模型整体规模的增大，模型算法也出现了稀疏化和复杂化的趋势，AI编译面临新的挑战，如何选择并行算法，如何部署分布式数据访问，如何在计算的同时隐藏通讯时间等。\n\n你将依据模型发展趋势和自研AI芯片的特点参与设计和迭代AI编译器的方案，并和团队一起基于最先进的AI原生软件技术开发新的编译器。你的工作将决定自研AI芯片能否被新的模型充分利用，意义重大。\n\n• 面向LLM模型，开发图编译器和算子编译器\n• 设计编译器中间表示，解决模型自动并行化、分布式数据、计算和通信隐藏等技术难题\n• 与硬件团队协作，参与性能分析，确保编译器能充分利用硬件特性",
