        "1.研究生在读或即将毕业，计算机科学、人工智能、机器学习、自然语言处理等相关专业背景",
        "2.具备扎实的机器学习和深度学习基础，熟悉Transformer、GPT、LLaMA等大模型架构，有模型训练经验者优先",
        "3.具备数据挖掘、数据工程相关经验，熟悉数据清洗、去重、增强等技术，有构建大规模数据集经验者优先",
        "4.具备评测体系构建经验，熟悉代码评测、模型评估等方法，有参与构建Coding Benchmark经验者优先",
        "5.在相关领域国际顶级学术会议（如NeurIPS、ICML、ICLR、ACL、EMNLP等）发表过高水平论文，或拥有相关核心技术专利者优先",
        "6.具备扎实的编程能力，熟练掌握Python等编程语言及PyTorch等深度学习框架，能够独立开展实验设计与代码实现",
