      "core_problem": "千问Qwen是由Token Foundry自主研发的超大规模语言模型，具备跨语言、跨任务的理解与生成能力。Qwen系列模型，涵盖参数量从几百 M 到T级的基座大语言模型，并相继推出Qwen-VL、Qwen-Audio、Qwen-Omni、Qwen-Coder、Qwen-Image等系列模型。从多轮对话到代码生成，从逻辑推理到内容创作，从单一多模态到全模态统一理解生成，Qwen 正在打造全球领先的全模态模型技术体系，推动AI在企业服务、开发者生态、个人用户等领域的深度应用，引领下一代人工智能的发展。\n\n随着模型参数规模持续增加以及全模态数据的爆发，大模型训练面临着极致的算力、显存与通信瓶颈。千问Qwen Infra团队，致力于突破大模型底层系统与框架的技术天花板，通过极致的工程优化释放硬件算力，为千问系列模型的高效迭代与大规模落地提供坚实的系统基座。团队在多个方向上进行探索（具体如下罗列），若你对以下一个或者多个课题感兴趣均欢迎投递：\n1、超大规模分布式训练系统\n（1）并行策略与通信优化：设计并优化超大规模模型的高效分布式训练架构（如3D/4D/5D并行），突破万卡集群的通信与显存瓶颈。\n（2）训练稳定性与容错机制：构建高可靠的训练容错与诊断系统，实现长稳训练、断点极速恢复与集群故障自动隔离，保障千亿/万亿参数模型的高效迭代。\n2、软硬协同与底层算子优化\n（1）高性能自定义算子研发：深入异构硬件底层，基于CUDA/Triton/TileLang/CuteDSL等开发高性能算子（如FlashAttention），实现计算密集型与访存密集型任务的极致加速。\n（2）软硬协同与架构调优：探索软硬件协同设计，针对特定硬件架构进行指令集与内存层级的深度调优，充分释放新型加速卡的算力潜能。\n3、长上下文与多模态训练系统\n（1）长上下文训练优化：针对超长序列场景，设计高效的注意力机制与显存管理策略，突破长文本训练的算力与显存限制，提升模型长程理解能力。\n（2）多模态训练管线构建：打造支持文本、图像、音视频等异构数据的高效多模态训练系统，优化多模态数据的加载、预处理与混合并行调度。",
