        "2、在计算机系统、高性能计算（HPC）、分布式系统、GPU架构、深度学习框架底层等领域有扎实的理论基础和工程实践经验，并至少在其中一个方向（如万卡集群训练、算子优化）产生具有行业影响力的创新性成果或落地经验",
        "3、在国际顶级计算机系统/体系结构会议或期刊（如OSDI、SOSP、ASPLOS、MLSys、EuroSys、ISCA等）以一作身份发表过论文，或在知名开源AI系统社区（如PyTorch, Megatron, DeepSpeed, vLLM, TensorRT-LLM等）有核心代码贡献，或在ASC、SC等超算竞赛中取得优异成绩",
        "3、对突破大模型算力瓶颈有极客热情，具备优秀的系统性架构思维和死磕底层的钻研精神，敢于挑战现有系统范式。能够独立排查并解决复杂的系统/性能疑难杂症，主导或深度参与过千卡/万卡级集群建设或核心推理引擎研发的人选优先",
        "4、具备极其扎实的代码功底，精通C++/Python，熟练掌握CUDA/Triton等GPU编程技术",
