    "id": 40,
    "title": "Agentic RL Instance:环境和Verifier构建-阿里星",
    "department": "阿里巴巴控股集团",
    "location": "北京",
    "source": "https://campus-talent.alibaba.com/campus/position/199908280005",
    "description": "你将深度参与 RL Instance 构建方法与自动化产线体系的前沿研究，具体包括： \n1. 高价值场景挖掘与问题构建 ：探索如何结合训练目标，科学确定 RL 数据的能力覆盖范围与优先级。通过深入分析主流 Benchmark 及模型评测结果，从海量、多源数据中挖掘高价值样本，并将其转化为清晰、可执行的问题描述——这是整条训练链路的起点，也是决定模型能力上限的关键一环。\n2. 自动化环境构建与 Verifier 设计 ：探索如何批量、规模化地构建 Agent 运行环境，并将模糊的质量目标拆解为可执行、可量化、可扩展的评估标准（Verifier / Rubric）。从正确性、完整性、鲁棒性等多维度设计评价体系，持续攻克 Reward Hacking 等前沿难题，确保评估信号始终与训练目标精准对齐——这是一项兼具工程严谨性与算法创造力的挑战。\n3. 从0到1搭建批量化、工业级的数据生产与验证 Pipeline，涵盖任务生成、轨迹采样、自动校验、质量过滤等环节。对 Rollout 结果进行预校验与失败原因分析，前置修复题目模糊、环境配置不合理等噪声问题，为后续训练提供可靠、可追溯的高质量数据资产。\n4. 与领域专家和后训练算法等团队紧密配合，将模型效果反馈转化为数据策略调整（任务难度、Reward 信号、标注规范等）；与标注、工程等团队协作，推动产线持续优化\n5. 持续对标业界最前沿方案，将业务实践沉淀为学术成果，支持在 NeurIPS、ICLR、ICML 等顶级会议发表高质量论文，或推动相关算法与工具的开源，在学术界与工业界建立个人及团队的行业影响力。",
    "requirementsText": "1. 计算机、数学/统计、电子信息或相关专业博士学历，具备 RL/Post-Training 方向的研究经历，或机器学习 Applied Scientist 相关工作经验，熟悉 PPO、GRPO、DAPO 等主流 RL 算法及其工程实现细节。\n2. 具备扎实的 Python 工程能力，熟悉主流 harness/agent 框架，能够独立完成数据处理脚本、自动化 Pipeline 的设计与开发；有大规模 RL 训练相关项目经验者优先。\n3. 具备较强的自驱力、学习能力、创新意识、沟通协作能力与抗压能力；对 LLM、AGI/ASI 等前沿方向抱有浓厚兴趣，认同并践行 AI Native 的工作范式。\n4. 在ICLR、ICML、CVPR、ICCV、ACL、NeurIPS等顶会上发表过高质量论文，有高质量github开源项目者优先（加分项）\n5. 具有业界 LLM/Agent 相关团队的实习经验者优先（加分项）\n6. 有某个领域任务深度经验者优先，如数学物理science，ACM，kernel研发，软件系统工程等（加分项）",
