    "description": "1、联合设计千问办公Agent Loop与云原生Runtime，以端到端任务效果为目标，推动模型、规划、上下文、工具执行和运行环境协同演进；\n2、研发长程任务规划、记忆与上下文管理、Tool-use、反思纠错和失败恢复机制，并结合Runtime状态、资源约束及故障信号实现动态重规划；\n3、设计Sandbox、Session、Checkpoint/恢复、工具执行、弹性调度和可观测体系，保障Agent任务稳定、连续、可复现地运行；\n4、建设贯穿模型—Loop—Skill—Runtime的全链路Trace、评测和问题归因体系，以线上数据驱动效果、稳定性和成本持续优化；\n5、支撑Coding、文档、IM、AI+硬件和企业工作流等创新场景，将核心突破沉淀为顶会论文、专利或开源成果。",
    "requirementsText": "1、计算机、人工智能、分布式系统、操作系统等相关专业博士，或极其优秀的硕士/本科；在LLM/Agent算法或云原生/分布式系统一侧具备深入、连续的研究积累，并有能力跨越另一侧完成联合设计；\n2、原则上在NeurIPS、ICML、ICLR、ACL、KDD、SOSP、OSDI、NSDI、EuroSys、ASPLOS等CCF-A/国际顶会发表过高水平论文（建议3篇及以上），或拥有同等影响力的开源及工业成果；\n3、深入掌握以下至少一个方向，并理解其与另一侧的关键接口：Agent规划、Tool-use、Memory、Context Engineering、强化学习与评测；或Sandbox、Serverless、分布式调度、状态存储、故障恢复与可观测性；\n4、具备极强编码和系统实现能力，熟练掌握Python、Go、Rust或C++，能够从研究原型推进到大规模生产系统；\n5、能洞察复杂问题并进行跨层建模，具备好奇心、创新意识和协同影响力，愿意同时为Agent效果与系统稳定性负责。\n\n加分项：主导过复杂Agent或大规模分布式系统；参与OpenCode、Codex类Harness、Kubernetes、Firecracker、gVisor、Ray、vLLM等有影响力的开源项目。",
