    "source": "https://campus-talent.alibaba.com/campus/position/199907640005",
    "description": "面向Agentic智能体大规模后训练、环境仿真瓶颈、高质量评测等核心挑战，本课题聚焦下一代大规模智能体强化学习基础设施建设，基于阿里ROCK平台与ROLL框架，突破万级并发仿真、标准化评测、海量数据自动化生产的技术瓶颈，为智能体持续自进化提供可扩展的训练底座。\n\n1. 研究高弹性、低开销的大规模环境调度机制，突破万级智能体仿真实例并行运行的技术瓶颈，攻克异构算力高效协同与资源弹性伸缩等核心问题，支撑超大规模群体智能训练。\n2. 研究多场景、全覆盖的标准化智能体Benchmark评测体系，构建统一的能力度量与算法迭代验证底座，解决当前智能体能力缺乏统一评测标准的行业难题。\n3. 研究大规模智能体交互数据自动化生产全链路技术，实现海量高质量训练数据高效量产，满足大模型智能体长周期强化学习迭代需求。\n4. 探索智能体驱动的大模型持续自进化框架，结合强化学习优化训练效率，增强大模型在对齐、推理、代码、数学等维度的能力，并将成果发表于顶级学术会议与回馈开源社区。",
