    "source": "https://campus-talent.alibaba.com/campus/position/199907640074",
    "description": "达摩院视频技术实验室致力最前沿AI及视频技术的研发，研究领域涉及先进视频编解码、生成AI视频、AI质量评估、VR/AR及全景视频等多个技术领域。实验室多位关键成员担任ITU-T视频编码专家组副主席，MPEG视频质量评估专题组主席，多项JVET技术专题组主席以及最新国际视频标准的编辑等职位。实验室的技术成果赋能多项主流视频标准，包括H.266/VVC、AVS3、VCM等，科研成果包括数十篇IEEE顶会顶刊论文以及数百项全球发明专利。\n视频技术实验室还致力将最新视频技术转化为高效编解码解决方案，实验室的旗舰软件编解码产品DAMO266在多届MSU大赛蝉联多项主客观指标冠军，目前已经规模落地优酷、视频云、钉钉、支付宝及国内超头部视频平台，显著提升用户体验，助力加速高清超高清视频的转化。\n视频技术实验室深耕AI视频编解码技术的研发和产业化，其主导的生成AI人脸视频压缩（GFVC）成为首个基于生成式AI技术的视频标准，并多次在联合国AI for Good峰会上展示。\n\n达摩院视频技术实验室诚邀优秀的应届博士和硕士毕业生加入我们，共同开发最先进AI视频技术，推动技术规模落地集团内外视频业务，进一步拓展AI视频技术的影响力，包括但不限于：\n1. 参与最新国际视频标准的制定，投入下一代视频标准H.267编码技术、生成式AI视频编码技术、3D/4D Gaussian Splatting编码技术、数字人Avatar编码技术等前沿标准化课题。\n2. 开发最新先进技术并服务于集团内外视频业务，包括云转码、视频直播和点播、全景视频和浸入式视频、端到端视频画质优化、创作意图还原等先进算法的开发和实现。\n3. 开发商业化价值高、实用性高的AI图像视频处理算法，覆盖更多的视频业务场景，包括图像/视频修复、空域/时域视频增强、关键物体的检测、分割、识别和跟踪等。\n4. 加速AI视频技术的产业化步伐，推动可解释AI和生成式AI技术的标准化和落地，解决AR/VR、数字人等新兴视频场景生产链路上的关键技术难点，为提升新兴视频应用场景下的音视频质量和体验带来飞跃性进展。\n\n同时阿里巴巴达摩院博土后工作站诚心欢迎优秀的博士毕业生加入。博士后工作站于2024年经国家人社部批复设立，拥有充沛的资源和丰富的应用落地场景，并支持最前沿的研究课题。目前在站博士后均为与清华、浙大、上海交大、复旦、中国科学院大学等一流高校联合培养。",
    "requirementsText": "1. 计算机和电子工程相关专业，博士学历优先（优异的硕士毕业生也会给于同样的考虑）。\n2. 硕博期间主攻AI视频技术和图像视频编解码技术，包括但不限于端到端视频编码、生成AI视频、可解释AI视频、3DGS、数字人、端到端视频体验优化等方向。\n3. 硕博期间有优异的学术产出，包括但不限于在Trans. on PAMI、Trans. on Image Processing 等IEEE顶刊和CVPR、ICIP、DCC等顶会上有首作论文发表，参加Challenge on learned image compression（CLIC）等国际知名图像视频压缩竞赛并获冠亚军奖等。\n4. 熟悉最新一代主流视频编解码标准（VVC、AV1、AVS3等），在标准参考软件上有算法实现经验的优先考虑。\n5. 优异的视频算法和工程优化能力，有实际AI视频应用开发和落地经验的优先考虑。\n6. 具有优异的编程能力、沟通能力、学习能力、团队协同能力和创新能力。",
