    "description": "1688作为B 端电商平台，服务百万级供给侧商家与亿级采购需求，正在打造B类电商的 OpenClaw：以 A2A（Agent-to-Agent）为核心的多智能体底座，将传统电商强依赖的搜推技术架构，升级为以买家需求为起点的端到端任务交付的A2A技术体系，极大提升买家的采购效率与生意确定性。该岗位的具体工作职责包括：\n1.买家多Agent 建设：基于用户行为/交易/询盘等数据，构建买家侧 Agent，打通多模态理解、需求推理与“找挑询付履”任务流规划，实现从买家需求到AI 找品/挑选、询盘/跟单、财税等端到端任务交付。\n2.买家/商家/平台AI客服建设：建设买家/商家/平台一体化智能客服，覆盖咨询导购、接待报价、平台服务与交易保障，支持多轮对话与流程化处理，提升服务效率与成交确定性。\n3.A2A 技术底座与链路落地：建设 A2A 多智能体与大模型底座，结合 SFT/Post-train、DPO/RLHF、RAG/知识增强、Agent 强化学习与工具/技能体系，提升长链路任务成功率，支撑“找—挑—询—付—履”端到端交付与规模化落地。",
