    "source": "https://campus-talent.alibaba.com/campus/position/199907720123",
    "description": "我们是阿里巴巴国际数字商业集团-Alibaba.com-Accio算法团队，Alibaba.com是全球最大的跨境B2B数字化平台，我们在24年11月推出AI Native应用Accio，并在25年9月推出Accio Agent版本，上线以来至今，用户数和订阅量以每月翻倍的速度飞速增长。我们团队有丰富的算力资源、自由的研究氛围以及靠谱的商业落地场景，我们正在寻找能够赋予大模型\"\"行动力\"\"的算法工程师，我们不止于让模型做出完美的回答，更致力于让模型成为能够自主闭环、解决复杂商业任务的Agent，你将参与从大规模数据合成到复杂强化学习环境搭建的全链路研发。\n\n1. 构建Agent专用合成数据管线：设计并实现自动化的合成数据方案，重点生产高质量的思维链、工具调用和自我修正轨迹；\n2. Agent交互环境搭建：构建高性能、可扩展的Agent框架和运行环境（如代码执行器、浏览器模拟器、数据库交互等），为模型提供实时反馈的环境；\n3. Agentic RL：应用并改进RL算法，提升模型在长程任务（Long-horizon tasks）中的成功率和鲁棒性；\n4. 评估体系建设：开发超越传统基准测试的动态评估方案，针对规划能力、工具选择准确率、幻觉控制及错误恢复能力建立量化指标。",
