    "id": 75,
    "title": "全球零售经营 AI Agent 智能算法革新-阿里星/Bravo Star",
    "department": "阿里国际数字商业集团",
    "location": "杭州",
    "source": "https://campus-talent.alibaba.com/campus/position/199907660048",
    "description": "阿里国际数字商业集团智能供应链物流和定价算法团队专注于海外零售经营的建设与优化，支持覆盖全球的千亿级零售行业。团队运用大模型、运筹优化、深度学习、强化学习、仿真等算法技术，解决需求洞察、价格损益、库存供给、供应链物流成本优化、履约体验等商业现实问题，重塑海外零售体系，创造社会价值。多年来团队紧跟工业界和学术界前沿，带来业务快速增长同时发表⾼⽔平学术论⽂20余篇（如AAAI、KDD、MS等），获得专利10余项。\n\n1、核心算法攻坚： 主导选品、定价、供应链、物流全链路的核心算法突破，解决跨域协同与复杂商业约束下的多目标优化难题；\n2、算法模型与业务深度融合： 推动 LLM/VLM 、强化学习、仿真优化等前沿算法在业务深水区的创新应用，设计基于复杂商业反馈的微调与对齐范式，打造直接驱动业务增长的核心领域模型；\n3、高不确定性下的分层强化学习与运筹优化： 构建多层强化学习体系并深度融合运筹优化技术，解决多时间尺度下的库存优化、在线分单与干线智能配舱等 NP-Hard 问题，在毫秒级内实现物流网络全局成本最优；\n4、基于 AI 的时序预测： 实现跨国别、多场域、冷启动场景下销量与时效预测模型的范式突破；\n5、业务闭环与生态建设： 将顶尖算法转化为真实的商业结果（规模、利润、效率）；引领团队技术方向，构筑产研结合的技术护城河。\n6、旨在构建一个对抗“时空错配”、统筹“信息流、资金流、实物流”的全球零售智能大脑。依托前沿的大模型应用技术与多 Agent 协同体系，我们将对选品、定价、库存、物流、损益等全链路进行 AI 化重构，彻底打通商业要素，激发从粗放增长到精准经营的飞轮效应。\n\n在这里，你有机会参与：\n1、技术攻坚与创新突破：聚焦零售多模态大模型与多 Agent 协同体系建设，攻坚跨国别、冷启动场景下的时序预测与动态定价等“硬核”算法难题。\n2、跨团队协作与知识沉淀：深度联动业务与工程团队，将前沿 AI 技术与选品、库存、履约等全链路节点彻底打通并沉淀为全局优化的商业应用架构。\n3、培养未来技术骨干：在应对全球亿级 SKU 与极其复杂的长链路履约战役中，将其培养为统筹“信息流、资金流、实物流”的复合型技术领军人物。\n4、引领技术方向：主导下一代全球零售智能大脑的算法演进，破解多目标冲突难题，沉淀出行业领先的智能供应链 Agent 产品与精准经营范式。",
    "requirementsText": "1、背景与学术： 人工智能、深度学习、运筹学或相关专业全球顶尖高校（C9/QS Top50）博毕业生。在 NeurIPS, ICML, KDD 等顶会发表过高质量论文或拥有核心应用型专利；\n2、技术深度： 精通 LLM 微调与业务落地、Prompt Engineering、多模态理解、强化学习或运筹优化，代码能力扎实（Java/C++/Python）；\n3、全局视野与商业体感： 具备极强的系统抽象能力，能将复杂的全球商业逻辑转化为严谨的数学或算法模型，具备跨领域视野。自我驱动强，皮实自省，勇于面对全球化的高难度挑战，善于跨域协同推动算法的商业落地。",
