    "description": "【团队介绍】\n我们是淘天集团用户算法团队，聚焦亿级用户全生命周期的兴趣理解和价值挖掘，致力于通过前沿AI技术，与手淘用户外投拉承、互动商品推荐、权益发放、消息触达及88vip会员等核心场景进行深度结合，为淘宝用户增长与长期价值提升持续注入动力，打造AI驱动的用户增长新引擎。\n我们以超大规模机器学习、生成式/多模态商品召回与排序、Agent创新应用、序列行为建模、因果推断与运筹优化等为核心技术引擎，不仅在传统的获客效率、用户活跃度、增量GMV和用户LTV等关键指标上持续突破，更在探索AI如何重塑用户理解、激发潜在需求、优化全局策略等前沿领域。\n这里，你将接触到最顶尖的技术挑战，参与定义电商未来的增长范式。加入我们，一起用AI领跑用户增长的未来！\n\n相关研究课题细分方向如下：\n● 课题1：大模型驱动的用户增长算法新范式\n    ○ 核心任务：利用大模型的世界知识与推理能力深度理解用户意图、预估长期价值，结合生成式推荐与导购Agent，重新定义电商用户增长的获客与转化链路。\n● 课题2： 大模型时代的电商权益生成式发放与可解释建模\n    ○ 核心任务：突破传统\"\"打分发券\"\"范式，用LLM构建增量因果预估与未来行为预测能力，并探索Post-CoT等白盒推理机制，让优惠券的发放既智能又可解释。",
    "requirementsText": "1. 计算机科学/人工智能/机器学习等相关领域的硕士或博士，具备扎实的编程基础（Python/C++/Java），熟悉常用算法与数据结构。\n2. 掌握机器学习基础理论，了解搜、推、广系统/自然语言处理/多模态/因果推断/运筹优化等至少一个领域。\n3. 有PyTorch/TensorFlow等框架使用经验，参与过算法竞赛（Kaggle/天池等）或开源项目者优先。\n4. 对AI技术充满好奇心，主动关注大模型、搜推广系统、NLP、强化学习、因果推断等领域前沿进展。\n5. 在顶级会议或高水平期刊发表过论文，或有复现前沿论文的经验者优先。\n6. 具备较强的问题拆解能力，能通过数据分析定位业务痛点并提出创新思路。\n7. 良好的沟通能力，能与工程师、产品经理高效协作，将技术方案转化为业务价值。\n8. 对电商场景有基本认知，愿意深入理解用户需求与商业逻辑。\n\n【加分项】\n1. 有大模型训练/微调经验（如Llama、GPT、多模态模型）或搜推广算法相关项目经历。\n2. 有海量数据处理经验或者大厂实习经验。\n3. 在算法竞赛中获得优异成绩（ACM-ICPC/挑战赛TOP10等）或者顶会论文发表。",
