    "source": "https://campus-talent.alibaba.com/campus/position/199907660047",
    "description": "阿里巴巴国际数字商业集团（AIDC）- 平台技术-AI Infra 团队。\n作为阿里国际的技术底座，我们负责支撑全球化电商（如 Lazada, AliExpress, alibaba.com等）及企业 AI 应用提效两大核心战略方向。我们的职责涵盖了从底层到顶层的全栈基础设施建设：\n（1）AI 核心基建： 打造 Agent 全生命周期平台，涵盖设计（低代码/Agent Framework）、运行时（RAG/Memory/Sandbox）、评测、观测治理及 AI 大模型网关等。\n（2）全链路基础架构： 深度掌控电商链路的每一环节，包括全球化终端技术、智能网络层、高性能接入层、应用中间件及各类基础软件。\n在这里，你不仅能参与定义下一代 AI 的运行范式，还能直面全球化超大规模分布式系统的技术挑战。\n\n你将参与：\n（1）Agent Native底座研发： 构建支持 Agent 设计、运行、评测与治理的全生命周期基建，支撑万级 Agent 在复杂业务场景下的规模化落地。\n（2）核心组件攻坚： 深度优化分布式 RAG、多级记忆管理、人机协同（HITL）及高性能 Agent 运行时。\n（3）AI 资产生态建设： 打造 AI 大模型网关，解决模型消费的极致成本与供给稳定性；基于 MCP 协议构建全球 Skill 市场，沉淀企业级 AI 资产。",
    "requirementsText": "（1）扎实的计算机根基：计算机、人工智能、数学等相关专业硕士及以上学历；精通数据结构、操作系统、网络编程、分布式系统等核心基础知识。\n（2）优秀的工程实现能力：精通 Linux 环境下 Java/Go/C++ 其中至少一门语言，具备良好的代码风格；能够独立解决复杂逻辑问题，对系统架构设计有浓厚兴趣和基本认知。\n（3）AI 技术视野：熟悉大语言模型（LLM）及智能体（Agent）的基本原理，了解 RAG、工具调用（Tool Use）等常见应用模式；关注生成式 AI 领域的前沿动态，能够快速学习并落地新技术。\n（4）软实力：具备出色的逻辑思维、沟通能力和团队协作精神，有强烈的技术好奇心和自驱力。\n（5）极客精神与自驱力： 面对复杂、模糊的问题有极强的拆解和解决能力，对定义下一代 AI 基础设施充满激情。",
