    "source": "https://campus-talent.alibaba.com/campus/position/199907620050",
    "description": "1.作为阿里星顶尖人才计划的一员，主导主流开源 AI 框架在真武芯片上的深度适配与性能优化，构建从训练到推理的完整高性能框架技术栈，涵盖主流SOTA框架，支撑 SOTA 大模型在自研芯片上的极致部署；\n2.构建覆盖端到端、算子级、Kernel 级的多粒度性能 Profiling 与基准测试体系，系统化定位真武芯片与开源框架交互中的性能瓶颈，形成可复用的性能调优方法论与工程实践 ；\n3.深入 SOTA AI 框架与模型的原理演进研究，持续开展业界竞品分析，挖掘真武芯片的差异化架构优势，制定针对性优化策略并推动落地，构建芯片的核心竞争力 ；\n4.面向主流开源社区贡献高质量代码与技术成果，提升真武芯片在 AI 框架生态中的影响力与技术话语权；同时为芯片客户提供深入的问题分析与定制化解决方案，直接服务核心业务 ；\n5.基于框架适配中积累的性能数据与瓶颈洞察，构建关键场景的性能预测与仿真模型，在芯片设计阶段提前进行精度与性能验证；与计算加速库、通信库、编译器、CMODEL 等团队紧密协作，为芯片架构演进与 AI 软件栈优化提供框架层面的深度洞察，你的研究成果将直接影响芯片的核心竞争力与生态建设。",
    "requirementsText": "1.计算机科学、电子工程、集成电路等相关专业硕士及以上学历；\n2.在深度学习系统、分布式计算、AI 框架或相关领域有深入研究经验，具备独立开展前沿课题研究的能力；\n3.精通 Python 与 C/C++，对数据结构与算法、操作系统、计算机体系结构有深刻理解，对主流深度学习框架底层实现有深入理解 ；\n4.熟悉 PyTorch、vLLM、SGLang、DeepSpeed、Megatron、Slime、Warp 等主流框架中至少一个的源码架构与核心机制，具备框架级性能分析与调优实战经验；\n5.具备敏锐的技术洞察力与强烈的自驱力，能够主动追踪前沿技术动态并推动技术突破，具备良好的学术写作与英文沟通能力。\n\n加分项：\n1.参与过知名开源 AI 框架项目（如 PyTorch、vLLM、SGLang、DeepSpeed 等）并有实质性代码贡献；\n2.在 MLSys、OSDI、SOSP、PPoPP、ASPLOS 等会议发表过相关论文；\n3.有大模型推理优化（如量化、KV Cache 管理、Speculative Decoding、PD 分离等）或分布式训练优化的实践经验；\n4.有性能预测、仿真建模相关研究或工程经验；\n5.在 ACM-ICPC、数学建模或各类 AI 性能挑战赛中取得过优异成绩。",
