    "source": "https://campus-talent.alibaba.com/campus/position/199907700045",
    "description": "我们致力于将前沿的多模态大模型技术与体育产业深度融合，探索人工智能技术在竞技体育领域的创新应用。围绕篮球、足球等核心运动场景，我们期望通过多模态感知、3D空间理解与跨模态推理，解决复杂运动分析中的核心挑战，打造下一代体育智能系统。\n1、体育多模态大模型创新：定义体育垂直领域的多模态大模型技术范式，实现文本、视觉、空间数据的联合建模，探寻并解决体育场景下的多模态对齐、战术推理与Agentic交互等核心挑战。\n2、3D视觉与运动分析：主导3D重建、人体跟踪与分割、动作识别等核心算法的研发，构建高精度的“球-人-场”协同感知系统，赋能战术分析、动作评估与辅助判罚等场景。\n3、场景驱动的算法落地：结合篮球/足球等真实业务场景，设计并优化大模型架构与3D视觉算法，提升模型在复杂动态环境下的效果、效率与鲁棒性，主导从数据构建到部署的端到端技术闭环。\n4、前沿技术探索：紧跟LLM、Diffusion Models、强化学习及3D视觉领域的最新进展，快速实验并迭代创新方案，拉升体育AI领域的SOTA水平，定义智能体育的技术新范式。",
