    "source": "https://campus-talent.alibaba.com/campus/position/199907820106",
    "description": "阿里云开源大数据平台 Flink 引擎团队是阿里云 Data+AI 技术体系的核心团队之一。围绕 Apache Flink 打造的实时计算平台，对内支撑通义千问、百炼、淘宝、天猫、钉钉、高德等业务的实时数据与 AI 业务，对外提供企业级实时计算云产品。阿里云 Flink 团队是 Apache Flink 社区最大的贡献者与推动者，引领了 SQL 分析、云原生、流批一体、湖仓一体、存算分离及 AI 转型等变革，并孕育了 Flink CDC、Paimon、Fluss、Flink Agents 等创新项目。团队立足开源，崇尚\"\"自由、平等、开放、互助\"\"的文化。\n\n岗位描述：\n1. 参与Apache Flink内核及Flink Agents开源项目的架构设计与开发,包括事件驱动Agent状态管理、动态工具链编排、LLM推理引擎集成等核心模块的建设\n2. 负责在Flink Checkpoint机制基础上设计Agent长期记忆、工具调用历史、环境交互状态的持久化与恢复机制,实现秒级故障恢复\n3. 探索基于Flink静态数据管道的Agent工具调用链动态组装、并行执行和结果聚合机制,支持复杂事件处理场景下的多步推理\n4. 支撑实时监控告警、自动化运维、实时风控等企业级Streaming Agent标杆客户场景,将技术成果沉淀为Flink Agents开源项目核心特性\n5. 推动流式Agentic基础架构方向的学术影响力和推动开源技术与社区持续发展。",
