    "source": "https://campus-talent.alibaba.com/campus/position/199907720108",
    "description": "我们专注于探索大模型的下一代范式，沿\"\"新模型架构、科学智能、多模态、可解释性\"\"四个方向推进前沿技术突破。如果你对Transformer之外的下一代架构、大模型与科学的深度融合、原生多模态统一建模、模型机理与XAI等方向抱有强烈热情，勇于挑战从理论到应用的难题，欢迎加入我们！\n\n具体职责如下：\n1、研究下一代基础架构：探索线性注意力、状态空间模型、原生多模态统一架构、理解与生成一体化等技术路线，突破Transformer在长上下文、推理效率与跨模态表征上的瓶颈，开发高性能训练与服务框架；\n2、推动大模型与科学研究融合：以\"\"科学是下一个coding\"\"为牵引，沿AI Scientist与生物数据×LLM联合建模两条路径攻坚，冲刺CNS顶刊并将成果转化为系统性云计算解决方案；\n3、攻坚多模态前沿技术：研究多模态联合推理、空间认知建模与原生多模态统一架构，突破跨模态语义鸿沟，提升垂直场景的泛化与协同推理能力，构建领域多模态技术产品体系；\n4、研发模型可解释性技术：建设多层级（神经元/模块/任务）XAI框架与工具链，为新架构验证、科学场景可信落地、多模态决策溯源提供方法论支撑，提升模型安全性、透明度与迭代效率。",
