    "source": "https://campus-talent.alibaba.com/campus/position/199907720110",
    "description": "我们在重新定义 Agent 时代的搜索。传统搜索返回链接与摘要，而 agent 时代的入口正在迁移——coding agent、browser agent、桌面 / 企业 agent都把搜索作为工具接入工作流。我们要做的是一个面向 agent 的下一代搜索平台：\n\n- 多模态：统一检索网页、文档、代码、图像、表格等异构内容；\n- 跨数据源：打通公开网页、垂直数据源与企业内部知识库，做带权限的统一检索与融合；\n- 可验证、可追溯：把搜索升级为可跨源验证、带证据链与引用的研究能力（Deep Search / Deep Research ）；\n- agent-native：通过 API / SDK / 插件 / MCP 等多种方式被各类 agent 调用，成为它们可信的信息层。\n\n你将和团队一起探索并定义全新的搜索形式与 agent 检索范式——而不只是优化既有搜索框。\n\n\n岗位职责\n1. 面向 Agent 的搜索系统研发\n- 参与设计与实现搜索 Agent 的运行时与编排框架：把 query 理解、计划拆解、多源检索、下钻抽取、排序、跨源验证、合成等环节，组织为可插拔、可观测的工作流；\n- 参与构建统一的多模态 / 跨数据源检索层，把不同搜索源与解析器抽象为标准化、可组合的工具与 connector；\n- 参与工具调用管道、记忆 / 证据服务与多 Agent 协调，并通过多种接入形态（API / SDK / MCP 等）对外提供标准化检索能力，让本平台成为各类 agent 与应用可信的信息层。\n2. 搜索智能与训练优化\n- 探索基于强化学习 / 反馈学习的搜索 Agent\n训练：把检索质量、引用正确性、跨源验证、成本与延迟等设计为奖励信号，持续提升 agent\n的检索决策与工具使用能力；\n- 研究面向 LLM 的上下文预计算、实时知识图谱 / 证据检索等技术，在可信度不打折的前提下，将检索与推理效率提升一个数量级。\n3. 质量、可信与可观测\n- 把可验证性与可追溯性做进系统：证据图、引用绑定、冲突识别、置信度，让结果可审计、可复用；\n- 参与设计带权限的检索边界（委托身份、source-level ACL）；参与长任务的检查点与故障恢复、语义化链路追踪与成本核算。\n4. 技术探索与影响力\n- 前瞻探索新的搜索形式——新的检索范式、交互形态与 agent 协作模式，推动其在核心业务落地；\n- 鼓励将成果以论文、开源项目、技术分享的形式对外输出。",
    "requirementsText": "1. 基础条件\n- 2027 届应届硕士 / 博士，计算机科学、人工智能等相关专业；\n- 具备以下任一突出成果：顶会论文一作、国际顶级竞赛冠军，或高 Star 开源项目核心维护者。\n\n2. 系统架构深度\n- 扎实的分布式系统理论基础，深入掌握操作系统内核、网络协议栈、存储引擎底层原理；\n- 精通 Go / Python / Java / Rust 至少一门系统级语言，具备大规模生产级系统的架构设计与性能优化经验；\n- 深入了解后端技术栈（微服务 / API / 消息队列 / 缓存），有云原生（K8s / CI/CD /\n Serverless）或安全隔离技术（Docker / Kata / gVisor）经验。\n\n3. AI Agent 与搜索技术深度\n深入理解大模型技术原理与前沿进展，在以下至少一个方向具备业界领先的深度：\n- 搜索 / 检索 Agent：在多模态检索、跨数据源融合、知识图谱或大规模信息检索方向有深入研究或系统落地；有基于搜索 / 检索 Agent 进行强化学习（search agent RL、tool-use RL、RAG 优化等）的经验者尤佳；\n- Agent 核心组件：主导设计 Memory / RAG / 工具调用等关键组件，有创新性技术方案落地；\n- Agent 协议与互操作：熟悉 MCP / A2A 等协议，有协议层设计、实现或生态贡献经验。",
