    "source": "https://campus-talent.alibaba.com/campus/position/199907780095",
    "description": "阿里国际数字商业集团-供应链物流&定价算法团队专门负责阿里巴巴海外零售商品定价的建设和优化工作，业务覆盖全球，支持了千亿级别的零售行业、以及数以千万计的商品。\n我们支撑了阿里国际商业零售供的智能定价决策体系，我们的核心职责是通过商品定价、优化投资效率，提升平台的成交规模和损益。我们的工作涉及到国际商业数字零售定价问题的方方面面，充满了趣味和挑战。\n在这里，你将和我们一起，采用大模型、强化学习、运筹优化算法、仿真分析等持续解决定价和投资中的现实问题，不断创造价值，重塑整个海外零售商业体系，为社会带来更加美好的生活！\n在这里，您将与优秀的算法团队紧密合作，共同解决商业活动中的定价和投资问题，不断创造价值。让我们携手共创海外商业数字供应链的未来！\n我们的具体工作内容如下：构建国际电商场景下的定价和投资AI Agent, 通过建设多模态的商品特征、商家以及用户行为的理解能力，商品定价策略生成能力以及长序列投资决策学习能力，实现平台整体损益和规模的长期优化\n1. 商品、用户、商家多模态特征理解：以商品特征理解为例，利用多模态大模型同时处理商品图像（包装、材质、设计风格）和文本信息（品牌、功能描述、用户评论），学习能够反映定价相关属性的商品表示。研究如何从LLM输出中提取影响定价的关键特征，如品类归属、档次定位、功能复杂度、品牌溢价等。同时，研究如何从LLM的商品理解中抽象出可迁移的定价规律，包括同品类内的价格敏感度模式、不同档次商品的定价策略差异、可替代品之间的价格关联关系。设计知识迁移学习框架，将成熟品类的定价知识迁移到新品类或长尾商品。\n2. 商品定价策略生成能力：根据商品特征的理解自主制定价格策略，比如识别商品视觉特征（如包装颜色、尺寸展示、质感）对消费者价格预期的影响（例如，识别出\"高端包装\"应匹配更高价格锚点和更低折扣频率），并将其整合成商品的定价策略，同时需要满足平台对整体货盘的损益和规模要求。\n3. 长序列投资决策学习能力：根据对不同投资对象（商品、商家、用户），通过强学学习等方式学习历史决策结果，研究基于序列生成的未来定价/投资轨迹优化，实现对长期投资策略的提前规划和持续优化。",
