    "source": "https://campus-talent.alibaba.com/campus/position/199907820099",
    "description": "1. 负责医疗AI基础模型与智能体系统研发，包括医学影像基础模型、多病种诊断Foundation Model、医学影像生成模型、医学文本生成模型、循证医学Agent、医疗知识增强系统（RAG）及医疗AI评测体系等核心方向的研究与开发工作。\n2. 面向真实医疗场景，设计并研发具备感知、理解、推理和决策能力的新一代医疗智能系统，探索多模态大模型、Agent、多智能体协作、检索增强推理（RAG）等前沿技术在疾病筛查、诊断、治疗和临床决策支持中的应用。\n3. 分析业务技术需求，针对真实世界医疗场景设计合理的技术方案与研发路线，通过技术创新推动医疗AI在疾病筛查、报告/文本生成、循证决策及科研创新等方向的落地应用，并产出高质量学术论文、专利等成果。\n4. 持续跟踪大模型、多模态、Agent、Reasoning、AIGC等领域前沿进展，推动模型能力、训练效率、推理效率和系统性能持续提升，构建业内领先的医疗AI技术体系。\n5. 构建高质量医疗数据引擎，探索自动化数据生产、弱监督/自监督学习、合成数据生成等技术，提升医疗数据利用效率和基础模型能力。",
    "requirementsText": "1. 计算机科学、人工智能、电子工程、生物医学工程、数据科学等相关专业硕士及以上学历。\n2. 扎实掌握机器学习、深度学习、计算机视觉、自然语言处理或多模态学习相关理论与技术，具备Foundation Model、LLM、VLM、Agent、AIGC等相关方向研究经验者优先。\n3. 具备较强科研能力，在国际顶级会议或期刊（ICLR、NeurIPS、ICML、CVPR、ICCV、ECCV、ACL、EMNLP、MICCAI、TMI、TPAMI、MedIA等）发表过高质量论文者优先。\n4. 熟悉PyTorch、TensorFlow等深度学习框架，具备Transformer、Diffusion Model、多模态模型或Agent系统相关研发经验。\n5. 熟练掌握Python、C++等编程语言，熟悉Linux开发环境及大规模模型训练流程。\n6. 具备优秀的问题分析能力、创新能力和团队协作能力，对前沿技术保持强烈兴趣和持续学习热情。\n\n加分项：\n1. 在多模态学习、医学AI、Foundation Model、Agent、Reasoning、AIGC等方向有深入研究并发表高水平论文。\n2. 具备医疗影像分析、多病种诊断模型、医学文本生成、医学Agent、知识增强推理（RAG）或医疗AI评测体系相关经验。\n3. 具备大规模模型训练、推理优化、模型压缩、强化学习、合成数据生成等相关经验。\n4. 拥有高质量开源项目、竞赛成果或具有较大影响力的技术社区贡献。",
