    "description": "打造下一代生成式超算引擎，定义外卖行业技术新边界！\n淘宝闪购商物流日处理订单量超8000万，技术成果可直接驱动万亿级市场。\n突破生成式AI在商业领域的应用边界，打造“AI+运筹优化”的标杆案例。\n全程参与从理论研究到实际应用的完整流程，在真实项目中积累扎实的学术能力和高效的工程落地能力，成长为能解决复杂商业问题的“AI+业务”复合型人才。\n\n如果你渴望在生成式AI与商物流超算引擎领域的运筹优化、搜推算法等交叉领域留下技术印记，并推动外卖行业迈向智能决策新时代，我们期待与你共创无限可能！\n\n1. 生成式技术探索：深入研究生成式在搜推、调度、决策、路径规划等方向的前沿技术，参与构建端到端的生成式架构。\n2. 大模型技术融合：探索LLM在淘宝闪购业务场景中的应用，通过语义增强、知识推理等方式提升算法的多样性与可解释性，设计基于大模型的生成式检索、OneModel推荐等创新方案；融合 MIP、VRP、强化学习、图神经网络等技术，辅助传统优化求解器，构建端到端的智能决策系统。\n3. 分布式训练与推理：参与GPU集群环境下的分布式训练与推理优化，提升模型训练速度与在线服务性能，降低计算资源消耗。\n4. 算法优化及落地：能够基于 Transformer、强化学习、运筹优化等技术，优化生成式模型在商流、物流超算的效率与效果；结合工业级场景解决长序列建模、稀疏数据冷启动、多目标、动态化、实时化、长期价值等挑战。推动算法在淘宝闪购业务中的应用与落地。\n5. 跨团队协作：与工程、数据团队紧密合作，将算法需求转化为可落地的系统方案，通过 AB 实验验证模型效果，持续优化用户体验与业务指标。",
    "requirementsText": "1. 教育背景：计算机科学、人工智能、运筹学、数据科学等相关专业，博士研究生及以上学历，熟悉推荐系统、运筹等基础理论。\n2. 扎实的技术能力：精通Pytorch框架，熟练掌握 Transformer、扩散模型、对比学习等生成式模型技术；在大模型（LLM）、推荐系统、生成式 AI 等相关领域，有参与/主导过项目者优先。\n3. 出色的科研能力：参与或主导过有代表性的技术开源/科研项目工作，或发表过发表过大模型相关领域高质量、有影响力的论文，如：KDD、ACL、CIKM、NIPS等顶级会议相关论文，RecSys Challenge、Kaggle等竞赛并获奖。\n4. 快速学习与创新能力：对技术有强烈好奇心，能快速跟踪国际前沿研究，主动掌握新工具与新范式，具备创新突破和不断具备在模糊中找路径的韧性以及独立思考与解决复杂问题的能力。\n5. 团队协作与推动能力： 能够清晰表达技术思路，良好的沟通能力与团队协作精神，推动跨部门合作及目标落地。",
