    "source": "https://campus-talent.alibaba.com/campus/position/199907740037",
    "description": "负责设计与构建涵盖公共互联网信息的下一代 AI 搜索系统。主导从数据采集、索引构建到检索增强生成（RAG）的全链路架构设计，解决在百亿级文档规模下的高并发、低延迟及事实一致性难题。 核心职责包括： \n1、公网数据流水线架构设计：设计并实现高吞吐的公网数据采集与清洗系统，应对海量、多模态及动态变化的公开网络数据； \n2、混合检索与 RAG 引擎优化：构建基于“向量检索 + 关键词倒排索引”的混合检索架构，在百亿级文档库中实现毫秒级的高精度召回； \n3、大模型事实一致性校验：研发生成式搜索中的事实校验模块，抑制“幻觉”现象。 建立自动化评估框架，量化搜索结果的可解释性、准确性及来源权威性； \n4、高性能系统架构演进： 参与 AI 搜索系统的整体架构设计，推动系统从传统云原生架构向 AI 原生架构转型，整合分布式索引与大模型推理能力，平衡计算资源成本与系统性能。",
    "requirementsText": "1、计算机科学、人工智能或相关专业博士学历； \n2、精通 Python/C++/Go 中至少一门语言，具备深厚的数据结构与算法基础； \n3、搜索引擎核心技术：深入理解倒排索引原理、BM25/TF-IDF 算法及分布式索引构建策略，有亿级数据量索引优化经验者优先；\n4、向量检索与大模型：熟练掌握主流向量数据库及近似最近邻搜索（ANN）的优化，熟悉基础RAG 框架的实现与优化； \n5、分布式系统架构：具备高并发、高可用系统设计经验，熟悉 Kubernetes 及微服务架构； \n6、对 AI 搜索前沿技术（如 Agentic Search, Multi-modal Retrieval）有敏锐的洞察力； \n7、具备优秀的逻辑思维能力，能够独立拆解复杂问题并提出创新解决方案； \n8、良好的沟通协作能力，能够跨团队推动技术落地。 \n\n加分项： \n1、有主导或参与过工网搜索引擎或大型知识库问答系统的建设经验； \n2、在人工智能和计算机系统顶级会议发表过相关论文； \n3、ACM/ICPC等国际奖项获得者，主流开源项目活跃贡献者。",
