    "source": "https://campus-talent.alibaba.com/campus/position/199907720035",
    "description": "你将深度参与到千问VQA场景的优化&探索中，核心专注于提升 SearchAgent 在复杂视觉场景下的理解、推理及反思纠错能力。具体工作包括：\n1、高质量数据工程体系\n设计并构建复杂 Multi-Turn VL Search Trajectory 的数据合成与生产管线，探索自动化数据生成策略，模拟真实用户的复杂多轮搜索需求，构建包括CoT、ToolUse及Reflection路径的高质量训练数据集；\n2、VLM基础的感知/推理能力优化\n针对 Single Step 场景，优化VLM基座模型，显著提升其对复杂图像的理解、推理能力及工具调用的准确性，负责包括MiddleTrain和PostTrain在内的完整的训练阶段优化；\n3、Multi-Turn强化学习策略设计\n主导SearchAgent在Multi-Turn场景下的RL工作，探索&设计创新的RL方式与Reward System，有效激发Agent的自我反思与错误修正能力，提升Agent在长程依赖任务中的决策稳定性；\n4、Agent 架构优化与效率提升\n研究如何在保证检索效果的前提下，极致压缩 Trajectory长度，优化Agent 的搜索策略与规划机制，提升端到端的搜索效率。",
