    "description": "我们正在重新定义“千问”：从一个博学的对话者进化为具备执行力的数字实体。我们的核心使命是构建一套统一的认知架构，打破模型与现实世界的壁垒，实现从“语义理解”到“任务闭环”的跨越，让 AI 真正深入生产力场景，实现数字世界与物理世界的高效连接。你将参与以下研究：\n1、长程任务规划能力：研究复杂任务的精准拆解、动态编排与执行反馈机制，提升长链路任务完成率；\n2、记忆机制与上下文管理：研究短期/长期记忆、状态压缩、动态检索与上下文调度机制，在有限上下文窗口与资源约束下，提升跨轮一致性、任务连续性与复杂任务执行效率；\n3、复杂工具的自主学习与使用：推动 skills 的自主发现、组合与演化，提升在深度搜索、Browser Use、工程开发等场景中的高阶执行与组合优化能力；\n4、开放环境下的 Agentic Scaling 训练：探索类 OpenClaw 的开放任务训练范式，在兼顾资源利用率的同时，实现多 agents 的组织调度、合理的 context 管理与协同执行。",
