    "description": "岗位聚焦于构建面向下一代内容安全与商品治理的超级智能体系统（Super Agent），深度融合大模型认知能力及平台治理知识体系，推动风险治理从“人工规则+模型判别”向“自主感知—知识推理—动态决策—闭环干预”的智能体范式跃迁。核心职责包括：\n1、构建大模型驱动的商品治理体系：研发百亿级商品知识图谱，实现品牌、品类、款式、引流行为、黑产团伙等多维实体的高精度识别与关联推理；构建可解释、可演化的商品治理Agent，支持跨场景泛化与策略自适应；\n2、自编排可进化的智能审核流程：构建任务感知型Agent，支持新风险场景下的自动流程规划、工具调用与策略部署；设计大模型上下岗机制与在线迭代框架，保障系统持续学习与安全可控；\n3、构建十亿级商品流量下的违禁品智能防控体系：主导商品禁限售全覆盖能力建设，融合法律法规、平台规则与行业标准，构建动态更新的违禁品知识库；利用多模态大模型（文本、图像、属性、行为）实现高精度、低漏放的违禁商品实时识别与拦截；设计面向高并发、低延迟场景的在线防控架构，支撑日均十亿级商品曝光的毫秒级风险决策。",
