    "description": "Qteam 是阿里云旗下的 AI 编码产品团队，正在打造涵盖 AI IDE、AI 编码插件、AI Coding CLI 在内的下一代智能开发工具矩阵。我们相信 AI 将从根本上重塑开发者的编程方式——从代码补全到自主编程 Agent，从单点辅助到全流程智能化。在快速演进的产品矩阵背后，多平台交付复杂度、AI 功能非确定性质量验证、AI 安全攻击面防护、推理成本管理等工程化挑战亟待突破。我们的目标是构建一套 AI 原生的智能研发交付体系——让 AI 来保障 AI 产品的交付质量、安全与效率。你将能够参与：\n1.智能构建编排： 基于 LLM 构建智能 DevOps Agent，实现自然语言驱动的多平台流水线生成、构建失败自动根因分析与修复建议，将配置驱动的 CI/CD 升级为意图驱动的智能编排；\n2.AI 功能持续验证： 构建 ML 驱动的持续验证引擎，自动学习 AI 功能行为基线，实时检测异常偏移，支持智能灰度分析与自动回滚；\n3.安全编排与韧性工程： 将 AI 安全扫描左移至流水线，构建混沌工程韧性测试框架与 SLI/SLO 驱动的服务可靠性管理；\n4.成本管理与效能洞察： 构建 AI 推理成本细粒度归因与工程效能智能分析平台，自动识别瓶颈并生成优化建议。",
    "requirementsText": "1.硕士及以上学历在读或即将毕业，计算机科学、软件工程、人工智能等相关专业；\n2.了解 CI/CD、DevOps、云原生技术体系（Kubernetes、GitOps 等），有构建系统或研发效能平台开发经验者优先；\n3.熟悉 LLM 及 Agent 技术，有基于 LLM 构建智能应用经验者优先；\n4.精通至少一门主流编程语言（TypeScript/Python/Go/Java），能独立完成系统设计与实现；\n5.对持续验证、安全测试编排、混沌工程、工程效能等方向有研究经验者优先；\n6.在软件工程领域顶级会议（ICSE、FSE、ASE、ISSTA 等）发表过论文，或有高影响力开源项目经验者优先。\n\n【加分项】：\n1.有 IDE/插件/CLI 工具开发经验；\n2.有 AI 编码工具研发或深度使用经验；\n3.熟悉 Electron/VS Code 架构；\n4.有 AI 安全或 SRE/混沌工程实践经验。",
